"use client"
import { useState } from "react"
import React from "react"
import { Description, Dialog, DialogPanel, DialogTitle, DialogBackdrop } from "@headlessui/react"
import CustomImage from "@/components/molecules/customImage"
const DialogBox = ({
  title,
  description,
  showCloseIcon,
  children,
}) => {
  const [isOpen, setIsOpen] = useState(false)
  return (
    <>
      <button onClick={() => setIsOpen(true)}>Open dialog</button>
      <Dialog open={isOpen} onClose={() => setIsOpen(false)} className="relative z-50">
        <DialogBackdrop className="fixed inset-0 bg-black/40" />
        <div className="fixed inset-0 flex w-screen items-center justify-center p-4">
          <DialogPanel className="max-w-lg border bg-white">
            {/* Title  */}
            <div className="flex items-center justify-between p-4 border-b border-black/20">
              {title && <DialogTitle className="font-bold">{title}</DialogTitle>}
              {showCloseIcon &&
                <span onClick={() => setIsOpen(false)} className="inline-block size-4">
                  <CustomImage
                    imageSrc="/images/icon/close.png"
                    width={1000}
                    height={1000}
                    className="responsive-image-contain"
                  />
                </span>
              }
            </div>
            {description && <Description>{description}</Description>}
            <div>
              {children}
            </div>
            {/* <div className="flex gap-4">
              <button onClick={() => setIsOpen(false)}>Cancel</button>
              <button onClick={() => setIsOpen(false)}>Deactivate</button>
            </div> */}
          </DialogPanel>
        </div>
      </Dialog>
    </>
  )
}

export default DialogBox
